mapper.select:
SELECT cnum, cwriter, CCONTENT, cregdate, communitynum, mumbernum, row_num FROM (SELECT cnum, cwriter, CCONTENT, cregdate, communitynum, mumbernum, ROW_NUMBER() OVER(ORDER BY cnum desc) AS row_num FROM comments
cwriter like '%' || #{searchValue} || '%'
ccontent like '%' || #{searchValue} || '%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE comments
SET
    ccontent = #{ccontent} 
WHERE cnum = #{cnum}
